// Secrets are never kept (ADR-005 R22). Password managers mark what they copy with the nspasteboard.org markers, and
// some with their own; and some apps are simply never watched. Both are checked before any content is read.

import Foundation

public enum Filters {
    /// Kinds that mark a copy as secret, passing, or made by a program, not you.
    public static let secretTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "net.antelle.keeweb",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    /// Apps whose copies are never kept: password managers and Keychain Access.
    public static let defaultIgnoredApps: [(bundleId: String, name: String)] = [
        ("com.1password.1password", "1Password"),
        ("com.agilebits.onepassword7", "1Password 7"),
        ("com.bitwarden.desktop", "Bitwarden"),
        ("com.apple.keychainaccess", "Keychain Access"),
        ("com.apple.Passwords", "Passwords"),
    ]

    /// Whether a copy with these kinds, made while `app` was in front, may be kept.
    public static func allows(types: [String], app: String?, ignoredApps: Set<String>) -> Bool {
        if types.contains(where: secretTypes.contains) { return false }
        if let app, ignoredApps.contains(app) { return false }
        return true
    }
}
